<div class="mb-4"><h1 class="page-title">Reports</h1><p class="page-subtitle">Create an auditable record of operational reports generated by the team.</p></div><div class="row g-4"><div class="col-lg-5"><div class="card"><div class="card-body"><h5>Generate report record</h5><form method="post" action="?controller=reports&action=generate" class="vstack gap-3"><?= $this->csrfField() ?><input class="form-control" name="report_name" placeholder="Report name" required><select class="form-select" name="report_type"><option>Sales summary</option><option>Inventory valuation</option><option>Receivables</option><option>GPS activity</option><option>Cash book</option></select><textarea class="form-control" name="filters" placeholder="Filters or reporting period"></textarea><button class="btn btn-primary">Save report</button></form></div></div></div><div class="col-lg-7"><div class="card"><div class="card-body"><h5>Generated reports</h5><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Generated by</th><th>Date</th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td><?= htmlspecialchars($r['report_name']) ?></td><td><?= htmlspecialchars($r['report_type']) ?></td><td><?= htmlspecialchars($r['generated_by_name']??'System') ?></td><td><?= htmlspecialchars($r['generated_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
